args.input:
const text=(p,name,content,size=14,color="#18181B",weight="normal")=>Insert(p,{type:"text",name,content,fontFamily:"Inter",fontSize:size,fontWeight:weight,fill:color,textGrowth:"fixed-width",width:"fill_container",lineHeight:1.45});
const card=Insert(document,{type:"frame",name:"A · Notification settings card",x:1600,y:400,width:640,layout:"vertical",padding:24,gap:24,fill:"#FFFFFF",stroke:"#E4E4E7",strokeWidth:1,cornerRadius:12,reusable:true,placeholder:true});
text(card,"Card heading","Delivery preferences",20,"#18181B","600");
const row=Insert(card,{type:"frame",name:"Notifications control row",layout:"horizontal",alignItems:"center",gap:20,width:"fill_container"});
const label=Insert(row,{type:"frame",name:"Notifications label group",layout:"vertical",gap:4,width:"fill_container"});
text(label,"Notifications label","Email notifications",16,"#18181B","500");
text(label,"Notifications help","Turn updates on or off.",14,"#52525B");
const sw=Insert(row,{type:"frame",name:"Notifications switch · on",width:44,height:28,layout:"horizontal",padding:4,justifyContent:"end",alignItems:"center",fill:"#18181B",cornerRadius:20,metadata:{type:"control",role:"switch",checked:true,label:"Email notifications",independentOf:"email"}});
Insert(sw,{type:"ellipse",name:"Switch thumb",width:20,height:20,fill:"#FFFFFF"});
Insert(card,{type:"rectangle",name:"Divider",width:"fill_container",height:1,fill:"#E4E4E7"});
const field=Insert(card,{type:"frame",name:"Email field group",layout:"vertical",gap:8,width:"fill_container"});
text(field,"Email label","Email address",14,"#18181B","500");
const input=Insert(field,{type:"frame",name:"Email input",layout:"horizontal",padding:[12,14],width:"fill_container",stroke:"#D4D4D8",strokeWidth:1,cornerRadius:6,metadata:{type:"control",inputType:"email",label:"Email address"}});
text(input,"Email value","alex@example.test",16);
text(field,"Email hint","Use an address for this local prototype.",13,"#71717A");
const frequency=Insert(card,{type:"frame",name:"Frequency field group",layout:"vertical",gap:8,width:"fill_container"});
text(frequency,"Frequency label","Frequency",14,"#18181B","500");
const options=Insert(frequency,{type:"frame",name:"Frequency radio group",layout:"horizontal",gap:12,width:"fill_container",metadata:{type:"control",role:"radiogroup",value:"weekly"}});
for(const [title,selected] of [["Daily",false],["Weekly",true]]){const opt=Insert(options,{type:"frame",name:title+" option",layout:"horizontal",width:"fill_container",padding:14,gap:10,alignItems:"center",stroke:selected?"#18181B":"#D4D4D8",strokeWidth:1,cornerRadius:6,fill:selected?"#F4F4F5":"#FFFFFF",metadata:{type:"control",role:"radio",checked:selected}});Insert(opt,{type:"ellipse",name:title+" radio",width:16,height:16,stroke:selected?"#18181B":"#A1A1AA",strokeWidth:selected?5:1,fill:"#FFFFFF"});text(opt,title+" label",title,14,"#18181B",selected?"600":"normal");}
text(frequency,"Frequency help","One summary at your selected frequency.",13,"#71717A");
Update(card,{placeholder:false});
Print({card});
Get(card,(n,c)=>c.problems&&Print(n.id,n.name,c.problems));
TakeScreenshot([card]);
